mapper.select:
SELECT p.performance_id AS id, CASE WHEN p.work_item = 'TEAM' THEN 'Team' ELSE 'Individual' END AS type, p.title, LEFT(COALESCE(p.work_detail, ''), 24) AS coreTask, CASE WHEN p.start_date IS NOT NULL AND p.end_date IS NOT NULL THEN CONCAT(DATE_FORMAT(p.start_date, '%Y.%m.%d'), ' ~ ', DATE_FORMAT(p.end_date, '%Y.%m.%d')) WHEN p.start_date IS NOT NULL THEN DATE_FORMAT(p.start_date, '%Y.%m.%d') ELSE DATE_FORMAT(p.created_at, '%Y.%m.%d') END AS date, CASE WHEN p.status = 'ENDED' THEN '완료' WHEN p.status = 'WAITING' THEN '대기' ELSE '진행중' END AS status, COALESCE(p.achievement_rate, 0) AS progress, p.employee_id AS employeeId, COALESCE(NULLIF(p.work_detail, ''), p.title) AS description, COALESCE(NULLIF(pt.team_result_summary, ''), NULLIF(pp.result_summary, ''), NULLIF(p.comment, ''), '-') AS achievement FROM performance p LEFT JOIN performance_personal pp ON pp.performance_id = p.performance_id LEFT JOIN performance_team pt ON pt.performance_id = p.performance_id WHERE p.employee_id IN
#{employeeId}
ORDER BY p.created_at DESC

SELECT YEAR(base.target_date) AS scoreYear, MONTH(base.target_date) AS scoreMonth, ROUND(AVG(base.score)) AS score FROM ( SELECT COALESCE(mp.calculated_at, p.end_date, p.created_at) AS target_date, COALESCE(mp.score, p.achievement_rate, 0) AS score FROM performance p LEFT JOIN monthly_performance mp ON mp.employee_id = p.employee_id AND mp.year = YEAR(COALESCE(p.end_date, p.created_at)) AND mp.month = MONTH(COALESCE(p.end_date, p.created_at)) WHERE p.employee_id IN
#{employeeId}
AND DATE(COALESCE(mp.calculated_at, p.end_date, p.created_at)) >= #{windowStart} AND DATE(COALESCE(mp.calculated_at, p.end_date, p.created_at)) < #{windowEndExclusive} ) base GROUP BY YEAR(base.target_date), MONTH(base.target_date) ORDER BY YEAR(base.target_date), MONTH(base.target_date)

SELECT employee_id
FROM performance
WHERE performance_id = #{performanceId}

SELECT COUNT(*)
FROM performance
WHERE performance_id = #{performanceId}
  AND employee_id = #{employeeId}

SELECT COUNT(*)
FROM evaluation
WHERE evaluator_id = #{viewerEmployeeId}
  AND employee_id = #{targetEmployeeId}

SELECT base.employee_id AS employeeId, CASE WHEN EXISTS ( SELECT 1 FROM team_evaluation te_done WHERE te_done.evaluator_id = #{evaluatorId} AND te_done.appraisee_id = base.employee_id AND te_done.evaluation_year = YEAR(CURDATE()) ) THEN '완료' WHEN EXISTS ( SELECT 1 FROM performance p_wait WHERE p_wait.employee_id = base.employee_id AND p_wait.status = 'WAITING' ) THEN '진행 중' ELSE '평가 대기' END AS status, ROUND(AVG(COALESCE(p.achievement_rate, 0))) AS systemScore, ROUND(AVG((COALESCE(pr.communication_score, 0) + COALESCE(pr.solving_score, 0) + COALESCE(pr.responsibility_score, 0) + COALESCE(pr.team_contribution, 0)) / 4), 1) AS peerReviewScore, ROUND(AVG(COALESCE(pr.communication_score, 0)), 1) AS performanceAvg, ROUND(AVG(COALESCE(pr.responsibility_score, 0)), 1) AS attitudeAvg, ROUND(AVG(COALESCE(pr.team_contribution, 0)), 1) AS collaborationAvg, ROUND(AVG(COALESCE(pr.solving_score, 0)), 1) AS creativityAvg FROM ( SELECT DISTINCT employee_id FROM performance WHERE employee_id IN
#{employeeId}
UNION
SELECT DISTINCT employee_id FROM evaluation WHERE employee_id IN
#{employeeId}
UNION
SELECT DISTINCT appraisee_id AS employee_id FROM team_evaluation WHERE appraisee_id IN
#{employeeId}
) base LEFT JOIN performance p ON p.employee_id = base.employee_id LEFT JOIN evaluation ev ON ev.employee_id = base.employee_id LEFT JOIN peer_review pr ON pr.eval_id = ev.eval_id GROUP BY base.employee_id ORDER BY base.employee_id

SELECT base.employee_id AS employeeId, CASE WHEN EXISTS ( SELECT 1 FROM peer_review pr WHERE pr.reviewer_id = #{employeeId} AND pr.eval_id IN ( SELECT ev.eval_id FROM evaluation ev WHERE ev.employee_id = base.employee_id ) ) THEN TRUE ELSE FALSE END AS evaluated FROM ( SELECT DISTINCT employee_id FROM evaluation WHERE employee_id IN
#{employeeId}
UNION
SELECT DISTINCT employee_id FROM performance WHERE employee_id IN
#{employeeId}
) base ORDER BY base.employee_id

SELECT base.employee_id AS employeeId, ROUND(AVG(COALESCE(p.achievement_rate, 0))) AS systemScore, ROUND(AVG(COALESCE(pr.communication_score, 0)), 1) AS performanceAvg, ROUND(AVG(COALESCE(pr.responsibility_score, 0)), 1) AS attitudeAvg, ROUND(AVG(COALESCE(pr.team_contribution, 0)), 1) AS collaborationAvg, ROUND(AVG(COALESCE(pr.solving_score, 0)), 1) AS creativityAvg FROM ( SELECT DISTINCT employee_id FROM performance WHERE employee_id IN
#{employeeId}
UNION
SELECT DISTINCT employee_id FROM evaluation WHERE employee_id IN
#{employeeId}
) base LEFT JOIN performance p ON p.employee_id = base.employee_id LEFT JOIN evaluation ev ON ev.employee_id = base.employee_id LEFT JOIN peer_review pr ON pr.eval_id = ev.eval_id GROUP BY base.employee_id ORDER BY base.employee_id

SELECT p.employee_id AS employeeId, p.performance_id AS performanceId, p.title, CASE WHEN p.status = 'ENDED' THEN 'completed' ELSE 'in_progress' END AS status, DATE_FORMAT(p.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt FROM performance p WHERE p.employee_id IN
#{employeeId}
ORDER BY p.employee_id, p.created_at DESC
